      "session": 2,
      "subject": "law",
      "sourceId": "law-01",
      "number": 34,
      "stem": "上市有價證券之買賣，應於證券交易所開設之有價證券集中交易市場為之。但證券交易法亦設有例外規定，下列何者不屬之？",
