      "session": 2,
      "subject": "law",
      "sourceId": "law-01",
      "number": 35,
      "stem": "依證券交易法施行細則之規定，證券交易法第 36 條第 3 項第 2 款所定「發生對股東權益或證券價格有重大影響之事項」 ，下列何事項不包括在內？",
