      "sourceId": "investment-03",
      "number": 5,
      "stem": "下列敘述，何者為真？I.在任何一個特定期間，不同的產業間，報酬率有很大不同，所以產業分析在投資決策過程中還是必要的；II.同一產業內之個別企業間績效表現可能不一致，所以個股分析還是有其必要性",
