      "stem": "莞紗公司 X1 年 1 月 1 日流通在外普通股股數為 800,000 股。該公司 X1 年 1 月 1 日時有以前依面額發行之 5%可轉換公司債 18,000 張，每張面額$100，每張可轉換成 5 股普通股， X1 年無實際轉換發生。X1 年度淨利為$5,000,000，稅率為 25%。請問莞紗公司 X1 年之稀釋每股盈餘為多少？",
