      "stem": "竹林公司於X1年1月1日取得七賢公司10%股權，並於X2年10月1日再取得七賢公司30%股權，若七賢公司於X2年7月31日發放現金股利，請問竹林公司X2年度投資七賢公司應認列的投資收益為何？",
