      "subject": "accounting",
      "sourceId": "accounting-06",
      "number": 21,
      "stem": "路遙公司於X1年3月1日支付$308,000，取得面額$300,000、利率6%之公司債，所支付的款項中包含應計利息$3,000。路遙公司將該公司債分類為透過損益按公允價值衡量證券投資。公司債的到期日為X3年6月30日，付息日為每年6月30日及12月31日，X1年12月31日，該公司債的公允價值為$305,000。路遙公司X2年8月1日出售公司債共得款$311,000，假設手續費為$0。請問X2年路遙公司綜合損益表上證券投資之處分損益為多少？",
