      "stem": "東爺公司於X1年1月1日以營業租賃方式出租一設備予西牘公司，租期為三年。約定每年租金收入為$570,000，簽約時西牘公司支付押金$100,000給東爺公司，並約定租期屆滿時返還該設備，簽約時三年期銀行定存利率為3%，則東爺公司X1年損益表之租金收入為多少？",
