      "stem": "由甲、乙、丙三股票構成之投資組合，已知甲、乙、丙股票之β 值分別為 1.3，1.1，0.9，若投資於甲、乙、丙之資金比重分別為 0.2，0.3，0.5，則該投資組合之β 值為",
