      "stem": "假設在某個五年的投資期間中，無風險資產的平均報酬率為 4%。已知某投資美股的投資組合 P 與美國股市過去五年的平均月報酬、標準差(σ)及貝它值(β)如下：投資組合 P 市場投資組合平均報酬率 18% 15% 標準差 (σ) 20% 24% 貝它值 (β) 0.8 1.0 α 值 5% 0 請問：上述投資組合的崔納衡量值(Treynor measure)為多少？",
