      "stem": "假設老張目前持有 100 盎司的黃金，並在黃金期貨契約中採取短部位(short position)。已知黃金目前售價每盎司為 1,388 美元，12 月交割的期貨契約價每盎司為 1,395 美元。若明天黃金現貨價格為每盎司 1,393 美元，期貨價格為每盎司為1,398 美元。請問：基差 (basis)的變動為多少？",
